def edit(doc):
    # Collect objects by type suffix, preserving document order
    from collections import OrderedDict
    type_groups = OrderedDict()
    for obj in doc.Objects:
        if hasattr(obj, 'TypeId') and '::' in obj.TypeId:
            suffix = obj.TypeId.split('::')[-1]
            if suffix not in type_groups:
                type_groups[suffix] = []
            type_groups[suffix].append(obj)

    # Build label mapping
    label_map = {}
    for suffix, objs in type_groups.items():
        for idx, obj in enumerate(objs, start=1):
            new_label = f"{suffix}_{idx}"
            label_map[obj.Name] = new_label

    # Apply using refactor.relabel (preserves geometry)
    result = refactor.relabel(doc, label_map)
    return result

def edit(doc):
    # Collect all objects in document order and group by TypeId suffix
    type_counts = {}
    label_map = {}
    for obj in doc.Objects:
        tid = obj.TypeId
        if tid.startswith("PartDesign::") or tid.startswith("Sketcher::"):
            suffix = tid.split("::")[1]  # e.g. "Pad", "SketchObject"
            type_counts.setdefault(suffix, 0)
            type_counts[suffix] += 1
            n = type_counts[suffix]
            new_label = f"{suffix}_{n}"
            label_map[obj.Name] = new_label
    # Apply labels using refactor.relabel (preserves geometry)
    result = refactor.relabel(doc, label_map)
    return result

def edit(doc):
