def edit(doc):
    import re
    # Collect all PartDesign and Sketcher objects in document order
    objects = doc.Objects
    type_counts = {}
    result = {}
    for obj in objects:
        type_id = obj.TypeId
        if 'PartDesign' in type_id or 'Sketcher' in type_id:
            # Extract the part after '::'
            m = re.search(r'::(\w+)$', type_id)
            if m:
                short_type = m.group(1)
            else:
                short_type = type_id.split('::')[-1]
            type_counts[short_type] = type_counts.get(short_type, 0) + 1
            new_label = f"{short_type}_{type_counts[short_type]}"
            if obj.Label != new_label:
                obj.Label = new_label
                result[obj.Name] = new_label
    return result if result else None

def edit(doc):
    # Create or get the VarSet named "Dims"
    dims = None
    for obj in doc.Objects:
        if obj.TypeId == "App::VarSet" and obj.Label == "Dims":
            dims = obj
            break
    if dims is None:
        dims = doc.addObject("App::VarSet", "Dims")
        dims.Label = "Dims"

    # Find all PartDesign::Pad objects
    pads = [obj for obj in doc.Objects if obj.TypeId == "PartDesign::Pad"]

    for pad in pads:
        # Create a property name based on the pad's label (sanitize for property naming)
        prop_name = "Length_" + pad.Label.replace(" ", "_").replace("-", "_")
        # Add the property if it doesn't exist
        if not hasattr(dims, prop_name):
            dims.addProperty("App::PropertyLength", prop_name, "PadDimensions", "Length of " + pad.Label)
        # Set the property value to the current pad Length
        setattr(dims, prop_name, pad.Length)
        # Bind the pad's Length to the VarSet property
        pad.setExpression("Length", u"Dims." + prop_name)

    return {"count": len(pads)}

def edit(doc):
    # Create or get the VarSet named "Dims"
    varset = None
    for obj in doc.Objects:
        if obj.TypeId == "App::VarSet" and obj.Label == "Dims":
            varset = obj
            break
    if varset is None:
        varset = doc.addObject("App::VarSet", "Dims")
        varset.Label = "Dims"

    result = {"removed": []}

    # Process each PartDesign::Pad
    for obj in doc.Objects:
        if obj.TypeId == "PartDesign::Pad" and hasattr(obj, "Length"):
            pad_name = obj.Name
            # Create property name based on pad's label, sanitized for FreeCAD property naming
            prop_name = obj.Label.replace(" ", "_").replace("-", "_").replace(".", "_")
            # Ensure it's a valid property name (no leading digits, etc.)
            if prop_name[0].isdigit():
                prop_name = "Pad_" + prop_name

            # Add property to VarSet if not already present
            if not hasattr(varset, prop_name):
                varset.addProperty("App::PropertyLength", prop_name, "Group", prop_name)

            # Set the VarSet property value to the pad's current Length
            setattr(varset, prop_name, obj.Length.Value)

            # Bind the pad's Length to the VarSet property using expression
            obj.setExpression("Length", f"<<Dims>>.{prop_name}")

    return result

