def edit(doc):
    result = {}
    bodies = [o for o in doc.Objects if o.TypeId == 'PartDesign::Body']
    if not bodies:
        return None

    # Create a single VarSet to hold all parameters
    varset = doc.addObject("App::VarSet", "Parameters")
    varset.Label = "Parameters"

    # Add properties to VarSet for each dimension
    for body in bodies:
        body_name = body.Label
        for obj in body.Group:
            if obj.TypeId == 'PartDesign::Pad' and hasattr(obj, 'Length'):
                prop_name = f"{body_name}_Pad_Length"
                varset.addProperty("App::PropertyLength", prop_name, "Dimensions", f"Length of Pad in {body_name}")
                setattr(varset, prop_name, obj.Length)
                obj.setExpression('Length', f'Parameters.{prop_name}')
                result[obj.Name + '.Length'] = prop_name

    return result if result else None

