def edit(doc):
    import re
    # Collect all objects that are PartDesign or Sketcher (by TypeId containing "::")
    objs = []
    for o in doc.Objects:
        tid = o.TypeId
        if "::" in tid:
            # Only PartDesign::* and Sketcher::* (but not App::*)
            if tid.startswith("PartDesign::") or tid.startswith("Sketcher::"):
                objs.append(o)
    # Sort by document order (doc.Objects is in order, but we want stable order as they appear)
    # We'll just use the order they appear in doc.Objects
    # Count per type suffix
    counts = {}
    for o in objs:
        tid = o.TypeId
        suffix = tid.split("::")[1]  # e.g. "Pad", "SketchObject", "Body", etc.
        if suffix not in counts:
            counts[suffix] = 0
        counts[suffix] += 1
        new_label = f"{suffix}_{counts[suffix]}"
        o.Label = new_label
    # Return something to indicate success
    return {"relabeled": len(objs)}

def edit(doc):
    """Rename all PartDesign and Sketcher objects to <Type>_<n> form."""
    import re
    counters = {}
    for obj in doc.Objects:
        typeid = obj.TypeId
        # Only target PartDesign and Sketcher objects
        if not (typeid.startswith("PartDesign::") or typeid.startswith("Sketcher::")):
            continue
        # Extract short type name after '::'
        match = re.search(r"::(\w+)$", typeid)
        if not match:
            continue
        short = match.group(1)
        counters.setdefault(short, 0)
        counters[short] += 1
        n = counters[short]
        new_label = f"{short}_{n}"
        if obj.Label != new_label:
            obj.Label = new_label
    return {"relabeled": counters}

def edit(doc):
    # Get all objects in document order
    objs = doc.Objects
    # Counters per type suffix
    counters = {}
    # Collect rename pairs: old_label -> new_label
    rename_map = {}
    for obj in objs:
        type_id = obj.TypeId
        # Extract part after "::"
        if "::" in type_id:
            suffix = type_id.split("::", 1)[1]
        else:
            suffix = type_id
        # Skip non-PartDesign and non-Sketcher types
        if suffix in ("Body", "Origin", "Line", "Plane", "Point"):
            continue
        counters[suffix] = counters.get(suffix, 0) + 1
        new_label = f"{suffix}_{counters[suffix]}"
        if obj.Label != new_label:
            rename_map[obj.Name] = new_label
    # Apply relabel using refactor (safe, geometry-preserving)
    result = refactor.relabel(doc, rename_map)
    return result

