def edit(doc):
    # Create a VarSet named "Dims" if it doesn't exist
    varset = None
    for obj in doc.Objects:
        if obj.TypeId == "App::VarSet" and obj.Label == "Dims":
            varset = obj
            break
    if varset is None:
        varset = doc.addObject("App::VarSet", "Dims")
        varset.Label = "Dims"

    # Find the Pad object
    pad = None
    for obj in doc.Objects:
        if obj.TypeId == "PartDesign::Pad" and obj.Label == "Pad":
            pad = obj
            break

    if pad is None:
        return None

    # Get current Length value
    length_value = pad.Length

    # Add a property to the VarSet for this pad's Length
    prop_name = "PadLength"
    # Check if property already exists, if not add it
    if not hasattr(varset, prop_name):
        varset.addProperty("App::PropertyLength", prop_name, "Dimensions", "Pad Length")

    # Set the property value
    setattr(varset, prop_name, length_value)

    # Bind the pad's Length expression to the VarSet property
    pad.setExpression("Length", f"Dims.{prop_name}")

    return {"count": 1}

def edit(doc):
    # Create a Spreadsheet named "Dims" if it doesn't exist
    sheet = None
    for obj in doc.Objects:
        if obj.Name == "Dims":
            sheet = obj
            break
    if sheet is None:
        sheet = doc.addObject("Spreadsheet::Sheet", "Dims")
        sheet.Label = "Dims"

    # Find all PartDesign::Pad objects
    pads = [obj for obj in doc.Objects if obj.TypeId == "PartDesign::Pad"]

    # For each pad, create an alias and bind its Length expression
    for pad in pads:
        # Create alias name based on pad's label (sanitize for valid alias)
        alias = pad.Label.replace(" ", "_").replace("-", "_").replace(".", "_")
        # Ensure alias is unique by appending pad name if needed
        existing_aliases = sheet.getAliases() if hasattr(sheet, 'getAliases') else {}
        if alias in existing_aliases:
            alias = pad.Name + "_Length"

        # Set the cell value to current Length
        cell = sheet.getCellFromAlias(alias) if alias in existing_aliases else None
        if cell is None:
            # Find first empty row
            row = 1
            while sheet.get("A" + str(row)) != "":
                row += 1
            sheet.set("A" + str(row), str(pad.Length.Value))
            sheet.setAlias("A" + str(row), alias)

        # Bind pad's Length to spreadsheet cell
        pad.setExpression("Length", f"<<Dims>>.{alias}")

    return {"count": len(pads)}

def edit(doc):
    import FreeCAD
    # Create Spreadsheet if it doesn't exist
    ss = None
    for obj in doc.Objects:
        if obj.Name == "Dims" and obj.TypeId == "Spreadsheet::Sheet":
            ss = obj
            break
    if ss is None:
        ss = doc.addObject("Spreadsheet::Sheet", "Dims")
        ss.Label = "Dims"

    # Collect pads and their lengths
    pads = []
    for obj in doc.Objects:
        if obj.TypeId == "PartDesign::Pad" and hasattr(obj, "Length"):
            pads.append(obj)

    count = 0
    for pad in pads:
        alias = pad.Label + "_Length"
        # Set alias and value in spreadsheet
        ss.set(alias, str(pad.Length))
        # Bind pad's Length expression
        pad.setExpression("Length", f"Dims.{alias}")
        count += 1

    return {"count": count}

