def edit(doc):
    # First, check if there's a Body in the document
    bodies = [o for o in doc.Objects if o.TypeId == 'PartDesign::Body']
    if not bodies:
        return None

    # Lift all candidate literals across the document into a shared VarSet
    result = refactor.lift_all(doc, target="VarSet", container="Parameters")

    # Apply across all bodies to ensure each body is parameterised
    across_result = refactor.across_all_bodies(doc, target="Spreadsheet")

    # Merge any redundant features that may have been created
    merge_result = refactor.merge_redundant(doc, dry_run=False)

    # Combine results
    final_result = {}
    if result:
        final_result.update(result)
    if across_result:
        final_result.update(across_result)
    if merge_result:
        final_result.update(merge_result)

    return final_result if final_result else None

