        # Add property to VarSet (length property)
        varset.addProperty("App::PropertyLength", prop_name, "Dims", f"Length for {pad.Label}")
        setattr(varset, prop_name, pad.Length)

        # Bind pad's Length to the VarSet property
        pad.setExpression("Length", f"<<Dims>>.{prop_name}")

    return {"count": len(pads)}

