def edit(doc):
    # Step 1: Create or find the Parameters VarSet
    params = None
    for obj in doc.Objects:
        if obj.TypeId == "App::VarSet" and obj.Label == "Parameters":
            params = obj
            break
    if params is None:
        params = doc.addObject("App::VarSet", "Parameters")
        params.Label = "Parameters"

    # Step 2: Lift all candidate literals into the VarSet
    result = refactor.lift_all(doc, target="VarSet", container="Parameters")

    # Step 3: Ensure the Pad.Length expression uses the lifted alias if it exists
    pad = doc.getObject("Pad")
    if pad and hasattr(pad, "Length"):
        # Check if there's an alias for Pad.Length in the VarSet
        for prop in params.PropertiesList:
            if prop.startswith("Pad_Length"):
                expr = f"<<Parameters>>.{prop}"
                current = pad.getExpression("Length")
                if current is None or str(current) != expr:
                    pad.setExpression("Length", expr)
                break
        else:
            # No alias found; create one if the property is still a literal
            try:
                val = pad.Length
                if isinstance(val, float) or isinstance(val, int):
                    alias = "Pad_Length"
                    if alias not in params.PropertiesList:
                        params.addProperty("App::PropertyLength", alias, "Dimensions")
                        setattr(params, alias, val)
                    pad.setExpression("Length", f"<<Parameters>>.{alias}")
            except:
                pass

    # Step 4: Ensure LinearPattern properties use lifted aliases
    lp = doc.getObject("LinearPattern")
    if lp:
        for prop_name in ["Length", "Occurrences"]:
            for p in params.PropertiesList:
                if p.startswith(f"LinearPattern_{prop_name}"):
                    expr = f"<<Parameters>>.{p}"
                    current = lp.getExpression(prop_name)
                    if current is None or str(current) != expr:
                        lp.setExpression(prop_name, expr)
                    break
            else:
                try:
                    val = getattr(lp, prop_name)
                    if isinstance(val, (float, int)):
                        alias = f"LinearPattern_{prop_name}"
                        if alias not in params.PropertiesList:
                            if prop_name == "Length":
                                params.addProperty("App::PropertyLength", alias, "Dimensions")
                            else:
                                params.addProperty("App::PropertyInteger", alias, "Dimensions")
                            setattr(params, alias, val)
                        lp.setExpression(prop_name, f"<<Parameters>>.{alias}")
                except:
                    pass

    # Step 5: Lift sketch constraints (Width, Height) into Parameters
    sketch = doc.getObject("Sketch")
    if sketch:
        # Use refactor to lift sketch constraints if they are literals
        # The lift_all should handle this, but we also ensure explicit aliases
        constraints = sketch.Constraints
        for i, c in enumerate(constraints):
            if c.Name in ("Width", "Height") and c.Type == "Distance":
                alias = f"Sketch_{c.Name}"
                if alias not in params.PropertiesList:
                    params.addProperty("App::PropertyLength", alias, "SketchConstraints")
                    setattr(params, alias, c.Value)
                # Set expression on the constraint via the sketch
                # FreeCAD doesn't directly support expressions on individual constraints,
                # but we can set the constraint value with an expression using setDatum
                try:
                    sketch.setDatum(i, f"<<Parameters>>.{alias}")
                except:
                    pass

    return result

