def _parameterise_body(doc, body):
    # Create a single spreadsheet for the whole document if not exists
    ss_name = "Parameters"
    ss = None
    for obj in doc.Objects:
        if obj.TypeId == "Spreadsheet::Sheet" and obj.Label == ss_name:
            ss = obj
            break
    if ss is None:
        ss = doc.addObject("Spreadsheet::Sheet", ss_name)
        ss.Label = ss_name

    # Get all features in this body that have literal dimensions we can lift
    candidates = refactor.lift_candidates(doc)
    # Filter candidates belonging to this body
    body_candidates = []
    for c in candidates:
        obj = doc.getObject(c["object"])
        if obj and hasattr(obj, "InList"):
            # Check if object is inside this body
            if obj.isDerivedFrom("PartDesign::Feature") and obj.getParentBody() == body:
                body_candidates.append(c)
            # Also include the body itself if it has properties? Not needed here
        elif obj and obj.Name == body.Name:
            # Direct body property? Unlikely for dimensions
            pass

    # For each candidate, lift the literal to the spreadsheet
    for c in body_candidates:
        refactor.lift_literal(doc, c["object"], c["property"], target="Spreadsheet", container=ss.Label)

    # Also handle Pad.Length and LinearPattern.Length explicitly if not already lifted
    for obj in body.OutList:
        if hasattr(obj, "Length") and obj.TypeId == "PartDesign::Pad":
            # Check if it has an expression already
            if not obj.getExpression("Length"):
                refactor.lift_literal(doc, obj, "Length", target="Spreadsheet", container=ss.Label)
        elif hasattr(obj, "Length") and obj.TypeId == "PartDesign::LinearPattern":
            if not obj.getExpression("Length"):
                refactor.lift_literal(doc, obj, "Length", target="Spreadsheet", container=ss.Label)
        elif hasattr(obj, "Occurrences") and obj.TypeId == "PartDesign::LinearPattern":
            if not obj.getExpression("Occurrences"):
                refactor.lift_literal(doc, obj, "Occurrences", target="Spreadsheet", container=ss.Label)

    return {"parameterised": len(body_candidates)}

