def edit(doc):
    # Find all PartDesign Bodies
    bodies = [obj for obj in doc.Objects if obj.TypeId == 'PartDesign::Body']
    if not bodies:
        return None

    # Create a single VarSet shared by all bodies
    varset = doc.addObject("PartDesign::VarSet", "Parameters")
    varset.Label = "Parameters"

    # For each body, parameterise its features
    results = []
    for body in bodies:
        body_name = body.Name
        body_label = body.Label

        # Process each feature in the body
        for feature in body.Group:
            # Pad: lift Length
            if feature.TypeId == 'PartDesign::Pad' and hasattr(feature, 'Length'):
                if feature.getExpression('Length') is None:
                    alias = f"{body_label}_Pad_Length"
                    refactor.lift_literal(doc, feature, 'Length', target='VarSet', container=varset.Name, alias=alias)

            # Pocket: lift Length
            if feature.TypeId == 'PartDesign::Pocket' and hasattr(feature, 'Length'):
                if feature.getExpression('Length') is None:
                    alias = f"{body_label}_Pocket_Length"
                    refactor.lift_literal(doc, feature, 'Length', target='VarSet', container=varset.Name, alias=alias)

            # LinearPattern: lift Length and Occurrences
            if feature.TypeId == 'PartDesign::LinearPattern':
                if hasattr(feature, 'Length') and feature.getExpression('Length') is None:
                    alias = f"{body_label}_LinearPattern_Length"
                    refactor.lift_literal(doc, feature, 'Length', target='VarSet', container=varset.Name, alias=alias)
                if hasattr(feature, 'Occurrences') and feature.getExpression('Occurrences') is None:
                    alias = f"{body_label}_LinearPattern_Occurrences"
                    refactor.lift_literal(doc, feature, 'Occurrences', target='VarSet', container=varset.Name, alias=alias)

            # PolarPattern: lift Occurrences and Angle
            if feature.TypeId == 'PartDesign::PolarPattern':
                if hasattr(feature, 'Occurrences') and feature.getExpression('Occurrences') is None:
                    alias = f"{body_label}_PolarPattern_Occurrences"
                    refactor.lift_literal(doc, feature, 'Occurrences', target='VarSet', container=varset.Name, alias=alias)
                if hasattr(feature, 'Angle') and feature.getExpression('Angle') is None:
                    alias = f"{body_label}_PolarPattern_Angle"
                    refactor.lift_literal(doc, feature, 'Angle', target='VarSet', container=varset.Name, alias=alias)

            # Revolve: lift Angle
            if feature.TypeId == 'PartDesign::Revolve' and hasattr(feature, 'Angle'):
                if feature.getExpression('Angle') is None:
                    alias = f"{body_label}_Revolve_Angle"
                    refactor.lift_literal(doc, feature, 'Angle', target='VarSet', container=varset.Name, alias=alias)

            # Groove: lift Angle
            if feature.TypeId == 'PartDesign::Groove' and hasattr(feature, 'Angle'):
                if feature.getExpression('Angle') is None:
                    alias = f"{body_label}_Groove_Angle"
                    refactor.lift_literal(doc, feature, 'Angle', target='VarSet', container=varset.Name, alias=alias)

            # Hole: lift Diameter, Depth, etc.
            if feature.TypeId == 'PartDesign::Hole':
                for prop in ['Diameter', 'Depth', 'DrillPointAngle', 'CountersinkDiameter', 'CountersinkAngle', 'CounterboreDiameter', 'CounterboreDepth']:
                    if hasattr(feature, prop) and feature.getExpression(prop) is None:
                        alias = f"{body_label}_Hole_{prop}"
                        refactor.lift_literal(doc, feature, prop, target='VarSet', container=varset.Name, alias=alias)

            # Additive/Subtractive primitives: lift dimensions
            if feature.TypeId in ('PartDesign::AdditiveBox', 'PartDesign::SubtractiveBox'):
                for prop in ['Length', 'Width', 'Height']:
                    if hasattr(feature, prop) and feature.getExpression(prop) is None:
                        alias = f"{body_label}_{feature.TypeId.split('::')[-1]}_{prop}"
                        refactor.lift_literal(doc, feature, prop, target='VarSet', container=varset.Name, alias=alias)

            if feature.TypeId in ('PartDesign::AdditiveCylinder', 'PartDesign::SubtractiveCylinder'):
                for prop in ['Radius', 'Height']:
                    if hasattr(feature, prop) and feature.getExpression(prop) is None:
                        alias = f"{body_label}_{feature.TypeId.split('::')[-1]}_{prop}"
                        refactor.lift_literal(doc, feature, prop, target='VarSet', container=varset.Name, alias=alias)

            if feature.TypeId in ('PartDesign::AdditiveSphere', 'PartDesign::SubtractiveSphere'):
                if hasattr(feature, 'Radius') and feature.getExpression('Radius') is None:
                    alias = f"{body_label}_{feature.TypeId.split('::')[-1]}_Radius"
                    refactor.lift_literal(doc, feature, 'Radius', target='VarSet', container=varset.Name, alias=alias)

            if feature.TypeId in ('PartDesign::AdditiveCone', 'PartDesign::SubtractiveCone'):
                for prop in ['Radius1', 'Radius2', 'Height']:
                    if hasattr(feature, prop) and feature.getExpression(prop) is None:
                        alias = f"{body_label}_{feature.TypeId.split('::')[-1]}_{prop}"
                        refactor.lift_literal(doc, feature, prop, target='VarSet', container=varset.Name, alias=alias)

            if feature.TypeId in ('PartDesign::AdditiveTorus', 'PartDesign::SubtractiveTorus'):
                for prop in ['Radius1', 'Radius2']:
                    if hasattr(feature, prop) and feature.getExpression(prop) is None:
                        alias = f"{body_label}_{feature.TypeId.split('::')[-1]}_{prop}"
                        refactor.lift_literal(doc, feature, prop, target='VarSet', container=varset.Name, alias=alias)

            # Thickness: lift Value
            if feature.TypeId == 'PartDesign::Thickness' and hasattr(feature, 'Value'):
                if feature.getExpression('Value') is None:
                    alias = f"{body_label}_Thickness_Value"
                    refactor.lift_literal(doc, feature, 'Value', target='VarSet', container=varset.Name, alias=alias)

            # Draft: lift Angle
            if feature.TypeId == 'PartDesign::Draft' and hasattr(feature, 'Angle'):
                if feature.getExpression('Angle') is None:
                    alias = f"{body_label}_Draft_Angle"
                    refactor.lift_literal(doc, feature, 'Angle', target='VarSet', container=varset.Name, alias=alias)

        results.append(body_name)

    # Also handle sketch constraints if any
    for obj in doc.Objects:
        if obj.TypeId == 'Sketcher::SketchObject':
            # Lift dimensional constraints (DistanceX, DistanceY, Radius, etc.)
            # We'll lift the constraint values that are not already expressions
            for i, constraint in enumerate(obj.Constraints):
                if hasattr(constraint, 'Value') and constraint.Value is not None:
                    # Check if already an expression
                    expr = obj.getExpression(f'Constraints[{i}]')
                    if expr is None:
                        alias = f"{obj.Label}_Constraint_{i}"
                        refactor.lift_literal(doc, obj, f'Constraints[{i}]', target='VarSet', container=varset.Name, alias=alias)

    return {"parameterised": results, "varset": varset.Name}

