def edit(doc):
    # Collect all PartDesign and Sketcher objects in document order
    objects = doc.Objects
    type_counter = {}
    result = {}

    for obj in objects:
        type_id = obj.TypeId
        # Check if it's a PartDesign or Sketcher type
        if not ('PartDesign' in type_id or 'Sketcher' in type_id):
            continue

        # Extract the part after "::"
        if '::' in type_id:
            short_type = type_id.split('::')[1]
        else:
            continue

        # Increment counter for this type
        if short_type not in type_counter:
            type_counter[short_type] = 0
        type_counter[short_type] += 1

        # Build new label
        new_label = f"{short_type}_{type_counter[short_type]}"

        # Set the label if different
        if obj.Label != new_label:
            old_label = obj.Label
            obj.Label = new_label
            result[old_label] = new_label

    return {"renamed": result} if result else None

